// 启动 Express 网关子进程
// ==========================================
function startGateway(port) {
  // 确定 src/index.js 的正确路径（打包后在 resources/app/src/ 内）
  const isDev = process.env.NODE_ENV === 'development' || !app.isPackaged;
  const gatewayPath = isDev
    ? path.join(__dirname, '../src/index.js')
    : path.join(process.resourcesPath, 'app/src/index.js');

  // ✅ 关键修复：必须使用系统 node，而非 process.execPath（Electron 二进制）
  // 按优先级依次尝试常见 node 路径
  const fs = require('fs');
  const CANDIDATE_NODE_PATHS = [
    '/opt/homebrew/bin/node',   // macOS Apple Silicon (Homebrew)
    '/usr/local/bin/node',      // macOS Intel (Homebrew / nvm)
    '/usr/bin/node',            // Linux
    process.env.NODE_BINARY,   // 用户自定义（环境变量）
    'node',                    // PATH 中的 node（兜底）
  ].filter(Boolean);

  let nodeExecutable = 'node'; // 默认兜底
  for (const p of CANDIDATE_NODE_PATHS) {
    if (p === 'node') { nodeExecutable = p; break; } // PATH 兜底，不用 existsSync 检查
    if (fs.existsSync(p)) { nodeExecutable = p; break; }
  }

  console.log(`[Electron] Node binary: ${nodeExecutable}`);
  console.log(`[Electron] Starting gateway on port ${port}, path: ${gatewayPath}`);

  const env = Object.assign({}, process.env, {
    PORT: String(port),
    NODE_ENV: isDev ? 'development' : 'production'
  });

  gatewayProcess = spawn(nodeExecutable, [gatewayPath], {
    env,
    stdio: ['pipe', 'pipe', 'pipe']
  });

  gatewayProcess.stdout.on('data', (data) => {
    console.log(`[Gateway STDOUT] ${data.toString().trim()}`);
  });

  gatewayProcess.stderr.on('data', (data) => {
    console.error(`[Gateway STDERR] ${data.toString().trim()}`);
  });

  // 守护进程：网关异常退出时自动重启
  gatewayProcess.on('exit', (code, signal) => {
    console.warn(`[Gateway] Process exited with code=${code}, signal=${signal}`);
    if (restartCount < MAX_RESTARTS && mainWindow && !mainWindow.isDestroyed()) {
      restartCount++;
      console.log(`[Guardian] Auto-restarting gateway (attempt ${restartCount}/${MAX_RESTARTS})...`);
      setTimeout(() => startGateway(activePort), 1500);
    } else if (restartCount >= MAX_RESTARTS) {
      console.error('[Guardian] Max restart attempts reached. Please restart the app.');
    }
  });
}
